    //loads a language file
    loadlang: function (locale, name, data, isdefault) {
        if (!nu.languages) {
            nu.languages = [];
            nu.lang = {};
        }
        nu.languages.push({ locale: locale, name: name });
        nu.lang[locale] = data;
        if (isdefault)
            nu.defaultlang = data;
        else {
            //copy any missing elements from the default to the language file
            for (var key in nu.defaultlang) {
                if (!data[key])
                    data[key] = nu.defaultlang[key];
            }
        }
    },

    //set the current language locale - default is "en"
    setLocale: function (locale) {

        nu.locale = locale;
        nu.t = nu.lang[locale];
        $.cookie("elocale", nu.locale);

        //select language
        for (var i = 0; i < nu.languages.length; i++) {
            var lang = nu.languages[i];
            if (lang.locale == locale)
                lang.sel = true;
            else
                lang.sel = false;
        }
    },

    getarray: function (array, prop, val) {
        for (var i = 0; i < array.length; i++) {            
            if (array[i][prop] == val)
                return array[i];
        }
        return null;
    },

    addCommas: function (nStr) {
        if (nStr < 0)
            return gsv(nStr);

        nStr += '';
        x = nStr.split('.');
        x1 = x[0];
        x2 = x.length > 1 ? '.' + x[1] : '';
        var rgx = /(\d+)(\d{3})/;
        while (rgx.test(x1)) {
            x1 = x1.replace(rgx, '$1' + ',' + '$2');
        }
        return x1 + x2;
    },
