    loadGame: function (gameId, playerid) {

        //set the canvas size to enter the game.
        if (nu.isfacebook && !nu.gamecanvasready) {
            FB.Canvas.getPageInfo(
                function (info) {                   
                    nu.gamecanvasready = true;
                    FB.Canvas.setAutoGrow(false);
                    FB.Canvas.setSize({ height: info.clientHeight - 50 });
                    nu.loadGame(gameId, playerid);
                }
            );
            return;
        }
        nu.gamecanvasready = false;
        nu.ingame = true;
        nu.hide();

        vgap.apikey = nu.apikey;
        vgap.onexit = nu.exitVGAP;
        vgap.godmode = false;
        if (playerid)
            vgap.load(gameId, playerid);
        else
            vgap.load(gameId);
    },
