    //NU DATA HELPER FUNCTIONS
    getSector: function (id) {
        return nu.getArray(nudata.sectors, id);
    },
    getHull: function (id) {
        return nu.getArray(nudata.hulls, id);
    },
    getHullByName: function (hullname) {
        var name = hullname.toLowerCase();
        for (var i = 0; i < nudata.hulls.length; i++) {
            var hull = nudata.hulls[i];
            if (name == hull.name.toLowerCase())
                return hull;
        }
        return null;
            
    },
    getRaceByName: function (racename) {
        var name = racename.toLowerCase();
        if (name == "the fascist empire" || name == "the fascists" || name == "fascist")
            return this.getRace(4);
        for (var i = 0; i < nudata.races.length; i++) {
            var race = nudata.races[i];
            if (name == race.name.toLowerCase() || name == race.shortname.toLowerCase() || name == race.adjective.toLowerCase())
                return race;
        }
        return this.getRace(0);

    },
    getAdvantage: function (id) {

        return nu.getArray(nudata.advantages, id);

    },
    getScenario: function (id) {
        return nu.getArray(nudata.scenarios, id);
    },
    getHullModels: function (id, raceid) {
        var models = new Array();

        //go to top
        var hull = nu.getHull(id);
        while (hull.parentid > 0 && hull.parentid != hull.id) {
            hull = nu.getHull(hull.parentid);
        }
        models.push(hull);

        //look down 
        var child = nu.getHullChild(hull.id, raceid);
        while (child != null) {
            models.push(child);
            child = nu.getHullChild(child.id, raceid);
        }
        return models;
    },
    getHullChild: function (id, raceid) {
        for (i = 0; i < nudata.hulls.length; i++) {
            if (nudata.hulls[i].parentid == id) {
                if (nu.isRaceHull(nudata.hulls[i].id, raceid))
                    return nudata.hulls[i];
            }
        }
        return null;
    },
    isRaceHull: function (hullid, raceid) {
        var race = nu.getRace(raceid);
        for (var i = 0; i < race.hullids.length; i++) {
            if (race.hullids[i] == hullid)
                return true;
        }
        return false;
    },
    hullImg: function (id, left, beams) {
        var picId = id;
        if (id > 3000)
            picId = id - 3000;
        else if (id > 2000)
            picId = id - 2000;
        else if (id > 1000)
            picId = id - 1000;

        if (picId == 71 && id > 1000 && beams)
            picId = picId + "-" + beams;

        if (left)
            return "http://play.planets.nu/img/hullsleft/" + picId + ".png";

        return "http://play.planets.nu/img/hulls/" + picId + ".png";
    },
    isfound: function (val, idlist) {
        var ids = idlist.split(',');
        for (var i = 0; i < ids.length; i++) {
            if (val == ids[i])
                return true;
        }
        return false;
    },
