    testRandoms: function (seed, count) {
        if (!count)
            count = 100;

        nu.api.testRandoms(seed, count, function (values) {
            var mt = new MersenneTwister(seed);
            var matching = true;
            for (var i = 0; matching && i < values.length; i++) {
                var server = values[i];
                var local = mt.genrand_int(119);
                console.log(i + ": " + server + "\t\t" + local);
                if (server != local) {
                    console.log("FAILED");
                    matching = false;
                }
            }
        });

    },

