ViewActivity.prototype = {


    //show this screen
    show: function () {

        //empty the content area
        nu.frame.content.empty();

        var activityid = nu.view.parseActivityId();

        if (activityid > 0) {
            nu.view.showThread(activityid);
            return;
        }

        //load the screen
        var screen = html.get("ActivityDetail", {}).appendTo(nu.frame.content);

        //tab navigation to subscreens
        screen.tabs.find("li").tclick(function () { window.location = "#/activity" + $(this).data("tab"); });

        nu.view.screen = screen;


        //direct load subscreens
        if (window.location.hash.indexOf("/summary") > 0) {
            //screen.summary.addClass("eselected");
            nu.view.showSummary();
            return;
        }
        if (window.location.hash.indexOf("/category") > 0) {
            screen.categories.addClass("eselected");
            nu.view.showCategory();
            return;
        }
        else if (window.location.hash.indexOf("/categories") > 0) {
            screen.categories.addClass("eselected");
            nu.view.showCategories();
            return;
        }
        else if (window.location.hash.indexOf("/search") > 0) {
            screen.search.addClass("eselected");
            nu.view.showSearch();
            return;
        }
        else if (window.location.hash.indexOf("/news") > 0) {
            screen.news.addClass("eselected");
            nu.view.showNews();
            return;
        }
        //else if (window.location.hash.indexOf("/advantages") > 0) {
        //    screen.advantages.addClass("eselected");
        //    nu.view.showAdvantages(screen, race);
        //    return;
        //}
        //else if (window.location.hash.indexOf("/officers") > 0) {
        //    screen.officers.addClass("eselected");
        //    nu.view.showOfficers(screen, race);
        //    return;
        //}

        screen.activity.addClass("eselected");

        var page = nu.view.parsePage();
        var pageid = "activity";
        var pagesuffix = "";
        if (page > 1)
            pagesuffix = "_" + page;

        pageid += pagesuffix;

        //default to activity
        if (!nu.data[pageid] || (new Date() - nu.data.activityloaded) > 120000) {
            nu.api.loadActivity(null, null, null, 50, page);
            return;
        }

        nu.view.screen.tabcontent.empty();
        
        var pagecount = Math.ceil(nu.data.activitycount / 50);
        var data = { id: 0, activity: nu.data[pageid], pagecontrols: nu.view.pageControls(page, pagecount), activityignoredcount: nu.data["ignoredcount" + pagesuffix] };

        if (nu.data.account) {
            nu.data.account.isuser = true;
            data.id = nu.data.account.id;
        }
        else {
            data.hidepost = true;
            data.hidereply = true;
        }

        var feed = html.get("ActivityFeed", data).appendTo(nu.view.screen.tabcontent);

        nu.bindFeed(feed, nu.data, data.id, 1);

    },
    parseActivityId: function() {

        if (window.location.hash.indexOf("/activity/") < 0)
            return 0;

        var path = window.location.hash.replace(/#\/activity\//g, "");
        if (path.indexOf("/") >= 0)
            path = path.substr(0, path.indexOf("/"));
        return path;
    },
    parseCategoryId: function () {

        if (window.location.hash.indexOf("/activity/category/") < 0)
            return 0;

        var path = window.location.hash.replace(/#\/activity\/category\//g, "");
        if (path.indexOf("/") >= 0)
            path = path.substr(0, path.indexOf("/"));
        return path;
    },
    parsePage: function () {
        var index = window.location.hash.indexOf("/page=")
        if (index < 0)
            return 1;

        var path = window.location.hash.substr(index + 6);
        if (path.indexOf("/") >= 0)
            path = path.substr(0, path.indexOf("/"));

        return parseInt(path);

    },
    pageControls: function (page, totalpages) {
        if (totalpages == 1)
            return null;

        var path = window.location.hash;
        if (path.indexOf("/page=") >= 0)
            path = path.substr(0, path.indexOf("/page="));

        var controls = [];
        if (page > 1)
            controls.push({ text: "<<", page: page - 1 });

        var maxpage = Math.min(Math.max(page + 3, 7), totalpages);
        var minpage = Math.max(maxpage - 6, 1);
        for (var i = minpage; i <= maxpage; i++)
            controls.push({page: i, current: (i == page)});

        if (page < totalpages)
            controls.push({ text: ">>", page: page + 1 });

        return { path: path, controls: controls };

    },
    showCategory: function () {

        if (!nu.data.categories) {
            nu.api.listCategories();
            return;
        }

        var categoryId = nu.view.parseCategoryId();

        var page = nu.view.parsePage();
        var pageid = categoryId;
        if (page > 1)
            pageid += "_" + page;

        if (!nu.data.categoryfeeds[pageid] || !nu.data.categoryfeeds[pageid].activity) {
            nu.api.loadActivity(null,null,null, 50, page, categoryId);
            return;
        }

        var category = nu.getarray(nu.data.categories, "id", categoryId);
        var count;

        if (categoryId == -1) {
            nu.data.categoryfeeds[pageid].title = "Uncategorized";
            count = nu.data.uncategorized;
        }
        else {
            nu.data.categoryfeeds[pageid].title = category.name;
            count = category.threadcount;
        }

        nu.view.screen.tabcontent.empty();

        var pagecount = Math.max(1, Math.ceil(count / 50));
        nu.data.categoryfeeds[pageid].pagecontrols = nu.view.pageControls(page, pagecount);

        var feed = html.get("ActivityFeed", nu.data.categoryfeeds[pageid]).appendTo(nu.view.screen.tabcontent);
        nu.bindFeed(feed, nu.data.categoryfeeds[pageid], 0, 0);

    },
    showSearch: function () {

        nu.view.screen.tabcontent.empty();

        var scr = html.get("SearchActivity").appendTo(nu.view.screen.tabcontent);

        scr.find("input").keydown(function (e) { if (e.keyCode == 13) nu.api.loadActivity(null, null, null, 50, 1, null, scr.searchtext.val(), function () { nu.view.showSearchResults(); }); });
        scr.searchbutton.tclick(function () {
            nu.api.loadActivity(null, null, null, 50, 1, null, scr.searchtext.val(), function () { nu.view.showSearchResults(); });
        });

    },
    showSearchResults: function () {
        var searchresults = $("#esearchresults");

        searchresults.empty();

        var data = { hidepost: true, activity: nu.data.activitysearchresults };

        var feed = html.get("ActivityFeed", data).appendTo(searchresults);

        nu.bindFeed(feed, nu.data.activitysearchresults, 0, 0);
    },
    showSummary: function() {

        //default to activity
        if (!nu.data.activity || (new Date() - nu.data.activityloaded) > 120000) {
            nu.api.loadActivity();
            return;
        }

        nu.view.screen.tabcontent.empty();

        var data = { activity: nu.data.activity };

        var feed = html.get("ActivitySummary", data).appendTo(nu.view.screen.tabcontent);

        feed.find(".eactsum").tclick(function () { window.location = "#/activity/" + $(this).data("id"); });

    },
    showCategories: function () {

        if (!nu.data.categories) {
            nu.api.listCategories();
            return;
        }

        nu.view.screen.tabcontent.empty();

        var scr = html.get("ListCategories", nu.data).appendTo(nu.view.screen.tabcontent);
        scr.find(".ecategoryrow").tclick(function () {
            window.location = "#/activity/category/" + $(this).data("id");

        });
        scr.find(".edelcategory").tclick(function () {
            var categoryid = $(this).data("id");
            nu.confirm("Are you sure you want to delete this forum category?", function () {
                nu.api.deleteCategory(categoryid);
            });
        });
        scr.addcategory.tclick(function () {
            //commas are not allowed in category names
            nu.api.addCategory(scr.newcategory.val().replace(/,/g, ""));
        });
        scr.find("a").tclick(function () {
            this.stopPropagation();
            return false;
        });

    },
    showNews: function () {

        //default to activity
        if (!nu.data.blogposts) {
            nu.api.blogPosts(20, nu.data);
            return;
        }

        nu.view.screen.tabcontent.empty();
        var list = $("<div id='egamelist'></div>").appendTo(nu.view.screen.tabcontent);
        html.get("BlogPosts", nu.data).appendTo(list);

    },
    showThread: function (id) {

        if (!nu.data.threads[id] || !nu.data.threads[id].activity) {
            nu.api.loadThread(id);
            return;
        }

        //load the screen
        var screen = html.get("ThreadDetail", {}).appendTo(nu.frame.content);

        var data = { hidepost: true, fullthread: true, id: 0, activity: nu.data.threads[id].activity, activityignoredcount: nu.data.threads[id].activityignoredcount };
        if (!nu.data.account)
            data.hidereply = true;
        else {
            nu.data.account.isuser = true;
            data.id = nu.data.account.id;
        }
        
        nu.view.activityid = id;

        var feed = html.get("ActivityFeed", data).appendTo(screen.thread);

        nu.bindFeed(feed, nu.data.threads[id], data.id, 1);

        $(".efeedline").show();

        nu.view.screen = screen;

        feed.selectcategory.tclick(function () {
            nu.view.showSelectCategory();
        });

    },
    showSelectCategory: function () {

        if (!nu.data.categories) {
            nu.api.listCategories(null, function () {
                nu.view.showSelectCategory();
            });
            return;
        }

        //select the categories for this thread.
        for (var i = 0; i < nu.data.categories.length; i++) {
            var category = nu.data.categories[i];
            
            var selcategory = nu.getarray(nu.data.threads[nu.view.activityid].categories, "id", category.id);
            if (selcategory != null)
                category.selected = true;
            else
                category.selected = false;
            
        }
        nu.showSelectCategory(function (categorynames) { nu.api.recategorize(nu.view.activityid, categorynames); });
    }


}

