function ViewAdmin() { };
ViewAdmin.prototype = {

    //show this screen
    show: function () {

        //empty the content area
        nu.frame.content.empty();

        //direct load subscreens
        if (window.location.hash.indexOf("/language") > 0) {
            nu.view.showLanguage();
            return;
        }

        //direct load subscreens
        if (window.location.hash.indexOf("/docs") > 0) {
            nu.view.showDocs();
            return;
        }

    },
    showLanguage: function (fordocs) {

        if (!nu.data.languages) {
            nu.api.loadLanguages();
            return;
        }
        if (!nu.data.currentlang)
            nu.data.currentlang = 1;

        var screen = html.get("LanguageAdmin", { languages: nu.data.languages, admincontrols: nu.data.account.securitylevel >= 2}).appendTo(nu.frame.content);

        screen.selectlanguage.val(nu.data.currentlang);

        screen.selectlanguage.change(function () {
            nu.view.showLanguageText(screen, parseInt($(this).val()));
        });

        if (nu.data.account.securitylevel >= 2) {
            screen.newlang.tclick(function () {
                var modal = html.get("EditLanguage");
                modal.save.tclick(function () {
                    nu.api.addLanguage(modal.locale.val(), modal.languagename.val());
                    nu.closemodal();
                });
                nu.modal(modal, "Language", "400px");
            });
            screen.addkey.tclick(function () {
                nu.api.addLanguageKey(1, screen.newkey.val());
            });
            screen.newkey.on('keyup', function (e) {
                if (e.which == 13) {
                    e.preventDefault();
                    nu.api.addLanguageKey(1, screen.newkey.val());
                }
            });
            screen.newkey.focus();
        }
        if (fordocs)
            nu.view.showDocText(screen, nu.data.currentlang);
        else
            nu.view.showLanguageText(screen, nu.data.currentlang);
       
    },
    showLanguageText: function (screen, languageid) {

        screen.editlang.empty();

        if (nu.data.languages.length > 0) {
            var english = nu.data.languages[0];
            var language = nu.data.languages[languageid - 1];

            var keys = new Array();
            for (var key in english.text) {
                keys.push({ key: key, english: english.text[key], text: (language.text[key] ? language.text[key] : "") });
            }

            var edittext = html.get("EditLanguageText", { keys: keys, admincontrols: nu.data.account.securitylevel >= 2 }).appendTo(screen.editlang);

            if (nu.data.account.securitylevel < 1)
                edittext.savefile.hide();

            edittext.savefile.tclick(function () {

                //we save the entire file as a new version
                var language = {};
                edittext.find(".elang").each(function () {

                    var key = $(this).data("key");
                    language[key] = $(this).val();
                });
                nu.api.saveLanguage(languageid, language);
            });

            edittext.find(".edel").tclick(function () {
                var key = $(this).data("key");
                nu.confirm("Are you sure?", function () {
                    nu.api.delLanguageKey(key);
                });
            });
        }
    },
    showDocs: function (screen, languageid) {

        if (!nu.data.doclist) {
            nu.api.loadDocList();
            return;            
        }

        if (window.location.hash.indexOf("/docs/") >= 0) {
            //individual doc edit
            var key = window.location.hash.replace(/#\/admin\/docs\//g, "");
            nu.view.showDoc(key);
            return;
        }

        var screen = html.get("EditDocList", { keys: nu.data.doclist, admincontrols: nu.data.account.securitylevel >= 2 }).appendTo(nu.frame.content);

        screen.find(".edel").tclick(function () {
            var key = $(this).data("key");
            nu.confirm("Are you sure?", function() { 
                nu.api.delDocKey(key);
            });
        });
        
        screen.addkey.tclick(function () {
            nu.api.addDocKey(screen.newkey.val());
        });
        screen.newkey.on('keyup', function (e) {
            if (e.which == 13) {
                e.preventDefault();
                nu.api.addDocKey(screen.newkey.val());
            }
        });
    },
    showDoc: function (key) {

        if (!nu.data.docs[key]) {
            nu.api.getDoc(key);
            return;
        }

        var screen = html.get("EditDocText", nu.data.docs[key]).appendTo(nu.frame.content);

        var raweditor = CodeMirror.fromTextArea(document.getElementById("edata"), {
            mode: 'text/html',
            tabMode: 'indent',
            autoCloseTags: true,
            lineNumbers: true,
            lineWrapping: true,
            extraKeys: { "Ctrl-Q": function (cm) { cm.foldCode(cm.getCursor()); } },
            foldGutter: true,
            gutters: ["CodeMirror-linenumbers", "CodeMirror-foldgutter"],
        });
        raweditor.setSize("100%", (((window.screen.availHeight - $("#edata").offset().top) / 2) * 0.95) + "px");
        raweditor.autoFormatRange({ line: 0, ch: 0 }, { line: raweditor.lineCount(), ch: raweditor.getTextArea().value.length });
        raweditor.setSelection({ line: 0, ch: 0 }, { line: 0, ch: 0 });

        //raweditor.on("changes", function () {
        //    if (!rawdelay) clearTimeout(rawdelay);
        //    rawdelay = setTimeout(_updatePreview, 200);
        //});

        screen.savedoc.tclick(function () {
            nu.api.saveDoc(nu.data.docs[key].languageid, key, screen.title.val(), raweditor.getValue());
        });

    }
}

