    uploadAttachment: function (fileObj, callback) {

        // STEP 2
        // create a FormData instance, and append the file to it
        var fd = new FormData();
        fd.append('file', fileObj);

        // STEP 3 
        // send the FormData instance with the XHR object
        var xhr = new XMLHttpRequest();
        xhr.open('POST', this.path + "/account/uploadattachment?version=2&name=" + encodeURIComponent(fileObj.name) + "&apikey=" + nu.apikey, true);
        xhr.onload = function (e) {
            var result = eval("(" + e.target.responseText + ")");
            if (result.error)
                nu.info(result.error);
            else {                
                if (callback)
                    callback(result);
                else
                    nu.view.show();
            }
        };
        xhr.send(fd);

    },
