    saveprofile: function (countryid, description, locale, enableemail, communitymentor, callback) {
        var request = { apikey: nu.apikey, countryid: countryid, locale: locale, description: description, communitymentor: communitymentor };
        if (enableemail != nu.data.account.emailenabled)
            request.enableemail = enableemail;

        nu.api.request("/account/saveprofile", request, function (data) {
            nu.indiOff();
            if (data.success) {

                nu.setLocale(locale);
                data.account.isregistered = data.isregistered;
                data.account.emailenabled = data.emailenabled;
                nu.data.account = nu.api.massageAccount(data.account); 

                if (callback)
                    callback();
                else
                    nu.view.show();
            }
            else {
                nu.info(data.error);
            }

        });
    },
    loadInbox: function(callback) {
        nu.api.request("/account/privateactivity", { apikey: nu.apikey }, function (data) {
            nu.indiOff();
            if (data.success) {

                for (var i = 0; i < data.activity.length; i++) {
                    var item = data.activity[i];

                    if (item.scope == 3) {
                        item.isprivatemessage = true;
                        if (item.targettype == 4)
                            item.isgroupmessage = true;
                    }

                    nu.api.massageActivity(item);

                    if (item._replies.length > 0) {
                        for (var j = 0; j < item._replies.length; j++) {

                            var reply = item._replies[j];

                            if (j != item._replies.length - 1)
                                reply.hideclass = "ehider";

                            nu.api.massageActivity(reply, true);

                        }
                        item.hidecount = item.replycount - 1;                        
                    }

                }

                nu.data.account.inboxloaded = new Date();
                nu.data.account.inbox = data.activity;

                if (callback)
                    callback();
                else
                    nu.view.show();
            }
            else {
                if (data.error.toLowerCase().indexOf("invalid api key") >= 0) {
                    nu.apikey = null;
                    nu.showSignin();
                }
                nu.info(data.error);
            }

        });
    },
    listCategories: function (activityid, callback) {
        var params = {includelatest: false};
        if (activityid)
            params.activityid = activityid;

        nu.api.request("/account/listcategories", params, function (data) {
            nu.indiOff();
            if (data.success) {

                if (!activityid) {
                    nu.data.categories = data.categories;
                    nu.data.uncategorized = data.uncategorized;
                    nu.api.massageCategories();

                    if (true) {
                        for (var i = 0; i < nu.data.categories.length; i++) {
                            var cat = nu.data.categories[i];
                            if (cat._latest) {
                                var item = cat._latest;
                                nu.api.massageActivity(item);
                                item.sumbody = nu.api.summarize(item, 120, true);
                                if (item._replies.length > 0) {
                                    for (var j = 0; j < item._replies.length; j++) {

                                        var reply = item._replies[j];

                                        if (j != item._replies.length - 1)
                                            reply.hideclass = "ehider";

                                        nu.api.massageActivity(reply, true);

                                    }
                                    item.hidecount = item.replycount - 1;

                                    //summary
                                    var lastreply = item._replies[item._replies.length - 1];
                                    item.sumbody = nu.api.summarize(lastreply, 120, true);
                                    item.sumreplysource = lastreply.sourcename;
                                }
                            }
                        }
                    }
                }
                else if (nu.data.threads[activityid])
                    nu.data.threads[activityid].categories = data.categories;

                if (callback)
                    callback();
                else
                    nu.view.show();
            }
            else {
                nu.info(data.error);
            }
        });
    },
