    loadThread: function(id, callback) {

        if (nu.data.account && !nu.data.account.ignoredactivities)
            nu.api.loadIgnoredActivities(function () { nu.api.loadThread(id, callback); });

        nu.api.request("/account/thread", { activityid: id }, function (data) {
            nu.indiOff();
            if (data.success) {

                for (var i = 0; i < data.activity.length; i++) {
                    var item = data.activity[i];

                    nu.api.massageActivity(item);

                    var ignoredcount = 0;
                    if (item._replies.length > 0) {
                        for (var j = 0; j < item._replies.length; j++) {

                            var reply = item._replies[j];

                            nu.api.massageActivity(reply, true);

                            if (reply.ignored)
                                ignoredcount++;

                        }
                    }

                }
                nu.data.threads[id] = { activity: data.activity, loaded: new Date(), categories: data.categories, activityignoredcount: ignoredcount };

                if (callback)
                    callback();
                else
                    nu.view.show();
            }
            else {
                if (data.error.toLowerCase().indexOf("invalid api key") >= 0) {
                    nu.apikey = null;
                    nu.showSignin();
                }
                nu.info(data.error);
            }
        });
    },
