    loadOfficers: function (account, callback) {
        nu.api.request("/account/officers", { accountid: account.id }, function (data) {
            nu.indiOff();
            if (data.success) {

                var lastlevel = data.officers[0].levelid;
                for (var i = 0; i < data.officers.length; i++) {
                    var officer = data.officers[i];
                    
                    officer.path = "#/officer/" + officer.id;
                    officer.levelname = nu.getLevel(officer.levelid).name;
                    officer.maxlevelname = nu.getLevel(officer.maxlevelid).name;
                    officer.showmaxlevel = (officer.levelid < 14 && officer.maxlevelid != officer.levelid);
                    officer.racename = nu.getRace(officer.raceid).name;

                    if (officer.turnsplayed == 0 && account.turnsplayed > 0)
                        officer.fade = true;

                    if (lastlevel != officer.levelid)
                        officer.levelchange = true;

                    lastlevel = officer.levelid;
                }

                var first = true;
                for (var i = 1; i < nudata.races.length; i++) {
                    var race = nudata.races[i];
                    if (nu.getarray(data.officers, "raceid", race.id) == null) {
                        data.officers.push({ raceid: race.id, fade: true, isnew: true, levelchange: first, racename: race.name, levelname: nu.getLevel(0).name });
                        first = false;
                    }
                }
                
                account.officers = data.officers;

                //if (account.isuser)
                    
                //else
                //    nu.data.accounts[account.username].officers = data.officers;

                if (callback)
                    callback();
                else
                    nu.view.show();
            }
            else {
                nu.info(data.error);
            }

        });

    },
