    loadOfficer: function (officerid, callback) {
        nu.api.request("/account/loadofficer", { officerid: officerid }, function (data) {
            nu.indiOff();
            if (data.success) {

                var officer = data.officer;
                officer.levelname = nu.getLevel(officer.levelid).name;
                officer.maxlevelname = nu.getLevel(officer.maxlevelid).name;
                officer.showmaxlevel = (officer.levelid < 14 && officer.maxlevelid != officer.levelid);
                officer.racename = nu.getRace(officer.raceid).name;
                officer.homeworld.dur = officer.homeworld.dur.toFixed(0);
                officer.homeworld.tri = officer.homeworld.tri.toFixed(0);
                officer.homeworld.mol = officer.homeworld.mol.toFixed(0);
                officer.homeworld.mc = officer.homeworld.mc.toFixed(0);

                var fleetadv = 0;
                var hullids = officer.activehulls.split(',');
                for (var i = 0; i < hullids.length; i++) {
                    var hull = nu.getHull(hullids[i]);
                    if (hull != null)
                        fleetadv += hull.advantage;
                }
                officer.fleetadv = fleetadv;

                var raceadv = 0;
                var advids = officer.activeadvantages.split(',');
                for (var i = 0; i < advids.length; i++) {
                    var adv = nu.getAdvantage(advids[i]);
                    if (adv != null)
                        raceadv += adv.value;
                }
                officer.raceadv = raceadv;
                officer.totaladv = fleetadv + raceadv;
                if (officer.totaladv > 500)
                    officer.overadv = true;

                nu.data.officers["officer" + officer.id] = officer;

                if (callback)
                    callback();
                else
                    nu.view.show();
            }
            else {
                nu.info(data.error);
            }

        });

    },
