    loadGameScores: function(gameid)
    {
        nu.api.request("/game/loadscores", { gameid: gameid }, function (data) { 
            nu.indiOff(); 
            if (data.error)
                nu.info(data.error);
            else {
                nu.data.games["game" + gameid].scores = data.scores;
                nu.api.processScores(nu.data.games["game" + gameid]);
                nu.view.show();
            }
        }, null, null, 1);

    },
    //build scoredata from game scores (more data, more charts)
    processScores: function (data) {
        data.scores.sort(function (a, b) {
            if (a.turn == b.turn)
                return a.ownerid - b.ownerid;
            else
                return a.turn - b.turn;
        });

        data.game.scoredata = {};
        var rowsize = data.game.slots + 1;
	    var scores = data.scores;
	    var categories = ["planets", "militaryscore", "inventoryscore", "starbases", "capitalships", "freighters"];
	    for (var c = 0; c < categories.length; c++) {
	        var category = categories[c];
	        var vals = [];
	        vals[0] = ["Turn"];
	        for (var i = 0; i < scores.length; i++) {
	            var score = scores[i];
	            vals[0][score.ownerid] = score.name;
	            var turn = score.turn;
	            if (vals[turn] == null) {
	                vals[turn] = new Array(rowsize).map(function () { return null; });
	                vals[turn][0] = score.turn;
	            }
	            vals[turn][score.ownerid] = score[category];
	        }       
	        data.game.scoredata[category] = vals;
	    }
    	   
	    // Total Ships and Ship Limit
	    var vals = [];
	    var freighters = data.game.scoredata.freighters;
	    var capships = data.game.scoredata.capitalships;
	    var size = capships[0].length;
	    vals[0] = capships[0];
	    for (var i = 1; i < capships.length; i++) {
	        var allships = 0;
	        var row = [];
	        row[0] = capships[i][0];
	        for (var j = 1; j < size; j++) {
	            var tships = capships[i][j] + freighters[i][j];
	            row[j] = tships;
	            allships += tships;
	        }
	        vals.push(row);
	        if (!data.game.shiplimitturn && allships >= 500) data.game.shiplimitturn = row[0];
	    }    	   
	    data.game.scoredata.totalships = vals;
	   
    },
