    updatePlayers: function () {

        var scr = nu.view.screen;
        scr.selectplayers.empty();

        var players = new Array();
        var teamid = 1;
        var teamplayers = 0;
        for (var id = 1; id <= scr.numplayers.val() ; id++) {

            var player = { playerid: id };

            //show the correct number of player boxes
            var raceoptions = new Array();
            raceoptions.push({ val: 0, name: "User Chooses Race" });
            for (var i = 1; i < nudata.races.length; i++) {
                var race = nudata.races[i];
                raceoptions.push({ val: race.id, name: race.name, selected: race.id == id });
            }
            raceoptions.push({ val: 100, name: "Computer - Random" });
            for (var i = 1; i < nudata.races.length; i++) {
                var race = nudata.races[i];
                raceoptions.push({ val: race.id + 100, name: "Computer - " + race.name });
            }
            player.selectoptions = raceoptions;

            if (scr.numteams.val() > 0) {
                
                player.hasteams = true;
                var teamoptions = new Array();
                for (var i = 1; i <= scr.numteams.val(); i++) {
                    teamoptions.push({ val: i, name: "Team " + i, selected:teamid == i });
                }
                player.teamoptions = teamoptions;

                teamplayers++;
                if (teamplayers == Math.ceil(scr.numplayers.val()/scr.numteams.val())) {
                    teamid++;
                    teamplayers = 0;
                }
            }

            players.push(player);
        }

        html.get("PlayerSelect", { players: players }).appendTo(scr.selectplayers);

        $(".eraceselect").change(function () {
            if ($(".eraceselect[value=0]").length > 0)
                scr.selectraces.show();
            else
                scr.selectraces.hide();
        });

        scr.shuffleteampositions.parent().toggle(scr.numteams.val() > 0);

    },
