    showInterest: function (screen, data) {

        screen.tabcontent.empty();

        if (!data.interest)
            return;

        for (var i = 0; i < data.interest.length;i++) {
            var acc = data.interest[i];
            if (acc.username == nu.data.account.username) {
                acc.isme = true;
                data.isinterested = true;
            }
            acc.path = nu.getPlayerPath(acc.username);            
        }

        var inter = html.get("GameInterest", data).appendTo(screen.tabcontent);

        if (inter.imin) {
            inter.imin.tclick(function () {
                nu.api.addinterest(data.game.id);
            });
        }

        inter.find(".eremove").tclick(function () {
            nu.api.removeinterest(data.game.id);
        });

        data.isinterested = false;

    },
