function ViewGames() { };
ViewGames.prototype = {


    //show this screen
    show: function () {

        //empty the content area
        nu.frame.content.empty();

        //load campaigns
        //if (!nu.data.games) {
        //    nu.api.loadgames();
        //    return;
        //}

        //load the screen
        var screen = html.get("Games", nu.data.games).appendTo(nu.frame.content);

        //tab navigation to subscreens
        screen.tabs.find("li").tclick(function () { window.location = "#/games" + $(this).data("tab"); });

        nu.view.screen = screen;
        var games;
        var startblitz = false;
        if (window.location.hash.indexOf("/open") >= 0) {

            screen.open.addClass("eselected");

            if (nu.data.opengames == null) {
                nu.api.listGames("2", "2,3,4,7", "opengames");
                return;
            }
            games = nu.data.opengames;
        }
        else if (window.location.hash.indexOf("/full") >= 0) {

            screen.full.addClass("eselected");

            if (nu.data.fullgames == null) {
                nu.api.listGames("2", "2,3,4,7", "fullgames");
                return;
            }
            games = nu.data.fullgames;
        }
        else if (window.location.hash.indexOf("/blitz") >= 0) {
            screen.blitz.addClass("eselected");

            if (nu.data.blitzgames == null) {
                nu.api.listGames("1", "5", "blitzgames");
                return;
            }
            if (nu.apikey)
                startblitz = true;
            games = nu.data.blitzgames;
        }
        else if (window.location.hash.indexOf("/finished") >= 0) {

            screen.finished.addClass("eselected");

            if (nu.data.finishedgames == null) {
                nu.api.listGames("3", "2,3,4,7", "finishedgames");
                return;
            }
            games = nu.data.finishedgames;
        }
        else if (window.location.hash.indexOf("/new") >= 0) {

            screen.joining.addClass("eselected");

            if (nu.data.newgames == null) {
                nu.api.listGames("1", "2,3,4,7", "newgames");
                return;
            }
            games = nu.data.newgames;
        }
        else if (window.location.hash.indexOf("/interest") >= 0) {

            screen.interest.addClass("eselected");

            if (nu.data.interestgames == null) {
                nu.api.listGames("0", "2,3,4", "interestgames");
                return;
            }
            games = nu.data.interestgames;

            var customswitched = false;
            for (var i = 0; i < games.length; i++) {
                var game = games[i];
                game.interestgame = true;
                if (!customswitched && game.shortdescription == "Custom Game") {
                    game.custombreak = true;
                    customswitched = true;
                }

                if (game.description.length > 200)
                    game.shortdesc = game.description.substring(0, 200) + " ...";
                else
                    game.shortdesc = game.description;
            }

        }
        else 
        {
            screen.championships.addClass("eselected");

            if (nu.data.championships == null) {
                nu.api.listGames("0,1,2,3", "6", "championships");
                return;
            }
            games = nu.data.championships;

        }

        var tabcontent = html.get("StandardGameList", { startblitz: startblitz, count: games.length, games: games, interestgame:window.location.hash.indexOf("/interest") >= 0, interestlink: window.location.hash.indexOf("/new") >= 0 }).appendTo(screen.tabcontent);

        $(".erendergamerow").tclick(function () { window.location = "#/sector/" + $(this).data("id"); });

        if (startblitz) {
            tabcontent.startblitz.tclick(function () { nu.view.startBlitz(); });
        }

    },
    startBlitz: function () {

        var win = html.get("StartBlitz", { races: nudata.races });
        nu.modal(win, "Start Blitz", "500px");

        $(".sro").attr("name", "sro");
        $("#selectrace0").attr("checked", "checked");
        $("#CreateBlitzButton").tclick(function () { nu.view.createBlitz(win); });
    },
    createBlitz: function (win) {
        
        var raceid = $("input[name=sro]:checked").val();
        var isprivate = win.makeprivate.is(":checked");
        var join = !win.hostonly.is(":checked");

        win.empty().html("<div>It can take up to 1 minute to create a blitz game.</div>");

        nu.api.createBlitz(raceid, isprivate, join, function () {
            nu.closemodal();
            if (join)
                nu.view.show();
            else
                window.location = nu.getPlayerPath(nu.data.account.username) + "/hosting";
        });
    }

}

