function ChatPlayer() { };
ChatPlayer.prototype = {
    end: null,
    session: null,
    play: function () {

        this.timeouts = new Array();

        $("<div id='chatscrollindicator'><i class='fas fa-angle-double-down'></i></div>").appendTo(this.target).hide();

        //check if there is the possibility to scroll down further and show indicator if so. 
        $(window).scroll(function () { chatPlayer.checkscroll(); });

        this.index = 0;
        this.show();

        //this is a new visitor - track some stats
        nu.api.chatTrack("play");

    },
    clear: function () {
        //$(this.target).empty();
        for (var i = 0; i < this.timeouts.length; i++) {
            clearTimeout(this.timeouts[i]);
        }
    },
    show: function () {
        var moment = this.chat[this.index];

        if (!moment) {
            if (this.end)
                this.end();

            return;
        }
        var id = "chat" + this.index;

        if (moment.text) {
            $("<div class='chatcontainer'><div class='chattext' id='" + id + "'></div></div>").appendTo(this.target);
            this.writeType("#" + id, moment.text, 0);
        }

        if (moment.image) {
            $("<div class='chatcontainer'><img class='chatimage' src='" + moment.image + "'/></div>").appendTo(this.target);
            this.timeouts.push(setTimeout(function () { chatPlayer.next(); }, moment.delay));
        }

        if (moment.video) {
            $("<div class='chatcontainer'><div class='videoWrapper'>" + moment.video + "</div></div>").appendTo(this.target);
            this.timeouts.push(setTimeout(function () { chatPlayer.next(); }, moment.delay));
        }

        if (moment.input) {
            $("<div class='chatcontainer'><input type='" + (moment.ispassword ? "password" : "text") + "' placeholder='" + moment.input + "' id='" + moment.mapto + "'/><div class='chatbutton' id='" + id + "'>OK</div><div class='chatinputerror' id='inputerror" + id + "'>" + (moment.errortext ? moment.errortext : "") + "</div></div>").appendTo(this.target);

            //enter key
            $("#" + moment.mapto).keyup(function (e) { if (e.keyCode == 13) $("#" + id).click(); }).select();

            $("#" + id).tclick(function () {
                var val = $("#" + moment.mapto).val();
                var error = moment.validate(val);
                if (error == null) {
                    $(".chatinputerror").empty();
                    $(".chatbutton").hide();
                    chatPlayer.next();

                    nu.api.chatTrack(val);

                }
                else {
                    $("#inputerror" + id).text(error);
                }
            });
        }

        if (moment.buttons) {
            nu.api.chatTrack("at " + id);

            for (var i = 0; i < moment.buttons.length; i++) {
                var button = moment.buttons[i];


                if (button.link) {
                    $("<div class='chatcontainer'><a href='" + button.link + "'><div class='chatbutton' " + (button.id ? "id='" + button.id + "'" : "") + ">" + button.text + "</div></a></div>").appendTo(this.target);
                }
                else {
                    var choose = function (btn) { return function () { chatPlayer.choose(btn); }; }; //closure

                    var div = $("<div class='chatcontainer'><div class='chatbutton' " + (button.id ? "id='" + button.id + "'" : "") + ">" + button.text + "</div></div>").appendTo(this.target);
                    if (button.helper)
                        $("<div class='buttonhelper'>" + button.helper + "</div>").appendTo(div);

                    div.tclick(choose(button))
                }
            }
        }

        if (moment.audio) {
            soundManager.createSound({
                id: id,
                url: moment.audio,
                autoPlay: true,
                onfinish: function () { chatPlayer.next(); }
            });
        }

        if (moment.select) {
            var div = $("<div class='chatcontainer'></div>").appendTo(this.target);
            for (var i = 0; i < moment.select.length; i++) {
                var option = moment.select[i];
                if (option.image) {
                    var img = $("<img src='" + option.image + "' class='chatselectimage' data-value='" + option.value + "'/>").appendTo(div);
                    img.tclick(function () { div.find("img").removeClass("chatimageselected"); $(this).addClass("chatimageselected"); $("#" + id).show(); });
                }
            }
            $("<div style='clear:left;'><div class='chatbutton' id='" + id + "' style='display:none;'>OK</div></div>").appendTo(div).tclick(function () { $(".chatbutton").hide(); $(".chatselectimage").hide(); $(".chatimageselected").width(100).height(100).show(); chatPlayer.next(); });
        }

        if (moment.callout) {
            moment.callout();
            chatPlayer.next();
        }

    },
    choose: function (button) {

        $(".chatbutton").hide();
        $(".buttonhelper").hide();
        $("<div class='chatcontainer'><div class='chattextright'>" + button.text + "</div></div>").appendTo(this.target);

        nu.api.chatTrack(button.text);

        if (button.moveto) {
            for (var i = 0; i < this.chat.length; i++) {
                if (this.chat[i].label == button.moveto) {
                    this.index = i;
                    break;
                }
            }
            this.show();
        }
        else
            chatPlayer.next();

    },
    checkscroll: function () {
        if ($(window).scrollTop() + $(window).height() >= ($(document).height() - 100)) {
            $("#chatscrollindicator").fadeOut();
        }
        else
            $("#chatscrollindicator").fadeIn();
    },
    next: function () {
        this.index++;
        this.show();
        this.checkscroll();
    },
    writeType: function (target, text, i) {
        if (i < (text.length)) {
            $(target).text(text.substring(0, i + 1));
            this.timeouts.push(setTimeout(function () { chatPlayer.writeType(target, text, i + 1) }, 50)); //Math.random()
        }
        else {
            //move to next step
            var moment = this.chat[this.index];
            if (moment.delay)
                this.timeouts.push(setTimeout(function () { chatPlayer.next(); }, moment.delay));
            else
                this.next();
        }
    }
}
var chatPlayer;
function ViewHowToPlay() { };
ViewHowToPlay.prototype = {

    //show this screen
    show: function () {

        //empty the content area
        nu.frame.content.empty();
            
        //individual doc to show
        var key = window.location.hash.replace(/#\/howtoplay\//g, "");

        if (!nu.data.docs["toc"]) {
            nu.api.getDoc("toc");
            return;
        }

        if (!nu.data.docs[key]) {
            nu.api.getDoc(key);
            return;
        }

        var toc = nu.data.docs["toc"];
        if (!toc.formatted) {
            toc.cleandata = toc.data.replace(/href=\"/g, "href=\"#/howtoplay/").replace(/external=\"/g, "href=\"");
            toc.formatted = true;
        }

        var doc = nu.data.docs[key];
        doc.cleandata = doc.data.replace(/href=\"/g, "href=\"#/howtoplay/").replace(/external=\"/g, "target=\"_blank\" href=\"");

        var admintools = false;
        if (nu.data.account && nu.data.account.securitylevel >= 1)
            admintools = true;

        var screen;
        var lkey = key.toLowerCase();
        if (lkey == "racesheet" || lkey == "racesheet2" || lkey == "badges" || lkey == "contrib-luck-comics" || lkey == "racesheetplus")
            screen = html.get("ShowWideDoc", { doc: doc, admintools: admintools }).appendTo(nu.frame.content);
        else {
            toc.cleandata = toc.cleandata.replace(" class='tocselected'", "").replace("#/howtoplay/" + key + "\"", "#/howtoplay/" + key + "\" class='tocselected'");
            screen = html.get("ShowDoc", { toc: toc, doc: doc, admintools: admintools }).appendTo(nu.frame.content);
            $("#toc ul:has(.tocselected)").show();
            $("#toc p:has(a[href='#/howtoplay/" + key + "']) + ul").show();
        }


    }
}

//register with ee
nu.views["howtoplay"] = new ViewHowToPlay();

function templater() { };
templater.prototype = {
    get: function (template, data) {

        //add language as "t"
        if (data) {
            data.t = nu.lang[nu.locale];
            data.help = nu.helplinks;
        }
        else
            data = { t: nu.lang[nu.locale], help: nu.helplinks };

        var obj = $(this.getmustache(template, data));

        //everything with an id is turned into an element on the return object
        obj.find("[id]").each(function () { obj[this.id.substr(1)] = $(this); });

        return obj;
    },
    getraw: function (template, data) {

        //add language as "t"
        if (data) {
            data.t = nu.lang[nu.locale];
            data.help = nu.helplinks;
        }
        else
            data = { t: nu.lang[nu.locale], help: nu.helplinks };

        return this.getmustache(template, data);
    },
    getsimple: function (template, data) {
        this[template].replace(/{{(\w*)}}/g, function (m, key) { return data.hasOwnProperty(key) ? data[key] : ""; })
    },
    getmustache: function (template, data) {
        return Mustache.render(this[template], data);
    }
}
