function ViewPost() { };
ViewPost.prototype = {


    //show this screen
    show: function () {

        //empty the content area
        nu.frame.content.empty();

        var postid = nu.view.parsePostId();

        if (!nu.data.posts[postid]) {
            nu.api.loadPost(postid);
            return;
        }

        //load the screen
        var screen = html.get("PostDetail", nu.data.posts[postid]).appendTo(nu.frame.content);

        nu.view.screen = screen;


        //load comments
        
        var data = { id: 0, hidepost: true, activity: nu.data.posts[postid].activity };

        if (nu.data.account) {
            nu.data.account.isuser = true;
            data.id = nu.data.account.id;
        }
        else {
            data.hidereply = true;
        }

        var feed = html.get("ActivityFeed", data).appendTo(screen.comments);

        nu.bindFeed(feed, nu.data.account, data.id, 1);

    },
    parsePostId: function() {

        if (window.location.hash.indexOf("/post/") < 0)
            return 0;

        var path = window.location.hash.replace(/#\/post\//g, "");
        if (path.indexOf("/") >= 0)
            path = path.substr(0, path.indexOf("/"));
        return path;
    }   


}

