function ViewRace() { };
ViewRace.prototype = {


    //show this screen
    show: function () {

        //empty the content area
        nu.frame.content.empty();

        var raceid = nu.view.parseRaceId();
        var race = nu.getRace(raceid);
        race.showstatus = false;

        //load the screen
        var screen = html.get("RaceDetail", race).appendTo(nu.frame.content);

        //tab navigation to subscreens
        screen.tabs.find("li").tclick(function () { window.location = "#/race/" + raceid + $(this).data("tab"); });

        nu.view.screen = screen;


        //direct load subscreens
        if (window.location.hash.indexOf("/hulls") > 0) {
            screen.ships.addClass("eselected");
            nu.view.showHulls(screen, race, "HullList");
            return;
        }
        else if (window.location.hash.indexOf("/advantages") > 0) {
            screen.advantages.addClass("eselected");
            nu.view.showAdvantages(screen, race);
            return;
        }
        else if (window.location.hash.indexOf("/officers") > 0) {
            screen.officers.addClass("eselected");
            nu.view.showOfficers(screen, race);
            return;
        }

        screen.activity.addClass("eselected");

        //default to activity
        if (!race.activity || (new Date() - race.activityloaded) > 120000) {
            nu.api.loadActivity(null, null, race);
            return;
        }

        if (!nu.data.account) {
            race.hidepost = true;
            race.hidereply = true;
        }

        screen.tabcontent.empty();

        var key = null;
        switch (race.id) {
            case 1:
                key = "feds";
                break;
            case 2:
                key = "lizards";
                break;
            case 3:
                key = "birds";
                break;
            case 4:
                key = "fascists";
                break;
            case 5:
                key = "privateers";
                break;
            case 6:
                key = "cyborg";
                break;
            case 7:
                key = "crystals";
                break;
            case 8:
                key = "empire";
                break;
            case 9:
                key = "robots";
                break;
            case 10:
                key = "rebels";
                break;
            case 11:
                key = "colonies";
                break;
            case 12:
                key = "horwasp";
                break;
        }

        if (!nu.data.docs[key]) {
            nu.api.getDoc(key);
            return;
        }

        var doc = nu.data.docs[key];
        doc.cleandata = doc.data.replace(/href=\"/g, "href=\"#/howtoplay/").replace(/external=\"/g, "target=\"_blank\" href=\"");
        html.get("ShowRaceDoc", { doc: doc }).appendTo(screen.tabcontent);
        //var feed = html.get("ActivityFeed", race).appendTo(screen.tabcontent);

        //nu.bindFeed(feed, race.id, 3);
    },
    parseRaceId: function () {
        var path = window.location.hash.replace(/#\/race\//g, "");
        if (path.indexOf("/") >= 0)
            path = path.substr(0, path.indexOf("/"));
        return path;
    },
    showOfficers: function (screen, race) {

        if (!race.allofficers) {
            nu.api.raceOfficers(race);
            return;
        }
        race.showofficers = race.allofficers;
        race.hasofficers = true;

        html.get("PlayerList", { races: [ race ] }).appendTo(screen.tabcontent);
    },
    showAdvantages: function (screen, race) {

        screen.tabcontent.empty();
        var advantages = nu.view.getAdvantageData(race);

        if (window.location.hash.indexOf("/advantages/") >= 0) {
            //show individual advantage
            var advid = window.location.hash.substr(window.location.hash.indexOf("/advantages/") + 12);
            nu.view.showAdvantage(screen, race, nu.getArray(advantages, advid));
            return;
        }

        var advlist = html.get("AdvantageList", { advantages: advantages }).appendTo(screen.tabcontent);
        advlist.find(".ehullrow").tclick(function () {
            var advid = $(this).data("id");
            window.location = window.location.hash + "/" + advid;
        });
    },
    showAdvantage: function (screen, race, advantage) {
        advantage.showstatus = false;
        var advdetail = html.get("AdvantageDetail", advantage).appendTo(screen.tabcontent);

    },
    showHulls: function (screen, race, template) {

        screen.tabcontent.empty();
        var hulls = nu.view.getHullData(race);

        if (window.location.hash.indexOf("/hulls/") >= 0) {
            //show individual hull
            var hullid = window.location.hash.substr(window.location.hash.indexOf("/hulls/") + 7);
            nu.view.showHull(screen, race, nu.getArray(hulls, hullid));
            return;
        }

        var hulllist = html.get(template, { hulls: hulls, costname: race.id == 12 ? "Clans" : "MC" }).appendTo(screen.tabcontent);

        hulllist.detail.tclick(function () {
            nu.view.showHulls(screen, race, "HullDetailList");
        });
        hulllist.overview.tclick(function () {
            nu.view.showHulls(screen, race, "HullList");
        });

        hulllist.find(".ehullrow").tclick(function () {
            var hullid = $(this).data("id");
            window.location = window.location.hash + "/" + hullid;
        });

    },
    showHull: function (screen, race, hull) {
        hull.showstatus = false;
        hull.prioritypoints = Math.ceil(hull.mass / 50);
        hull.ppp = hull.prioritypoints + 1;

        hull.costname = race.id == 12 ? "Clans" : "Megacredits";

        var hulldetail = html.get("HullDetail", hull).appendTo(screen.tabcontent);
    },
    getAdvantageData: function (race) {

        //construct race advantage list
        var advantages = new Array();
        for (var i = 0; i < race.advantageids.length; i++) {
            var adv = nu.getAdvantage(race.advantageids[i]);

            if (nu.isfound(adv.id, race.baseadvantages))
                adv.enabled = true;

            advantages.push(adv);
        }

        advantages.sort(function (a, b) {
            return a.id - b.id;
        });
        return advantages;
    },
    getHullData: function (race) {
        console.log(race);
        //construct race hull list
        var hulls = new Array();
        for (var i = 0; i < race.hullids.length; i++) {
            var hull = nu.getHull(race.hullids[i]);
            hull.img = nu.hullImg(hull.id, false, hull.beams);
            if (hull.launchers > 0)
                hull.haslaunchers = true;
            if (hull.beams > 0)
                hull.hasbeams = true;
            if (hull.fighterbays > 0)
                hull.hasbays = true;

            if (hull.special.length > 0)
                hull.hasspecial = true;

            if (hull.advantage > 0)
                hull.hasadv = true;

            if (hull.parentid > 0)
                nu.getHull(hull.parentid).child = hull;
            else
                hulls.push(hull);

            if (nu.isfound(hull.id, race.basehulls))
                hull.enabled = true;

        }

        hulls.sort(function (a, b) {
            if (a.techlevel == b.techlevel)
                return a.hullid - b.hullid;
            else
                return a.techlevel - b.techlevel
        });
        var sorted = new Array();
        for (var i = 0; i < hulls.length; i++) {
            var hull = hulls[i];
            sorted.push(hull);
            hull.indent = 5;
            if (hull.child) {
                sorted.push(hull.child);
                hull.child.indent = 30;
                if (hull.child.child) {
                    sorted.push(hull.child.child);
                    hull.child.child.indent = 60;
                }
            }
        }
        return sorted;
    }


}

//register with ee
nu.views["race"] = new ViewRace();
function ViewRaces() { };
ViewRaces.prototype = {


    //show this screen
    show: function () {

        //empty the content area
        nu.frame.content.empty();

        //load the screen
        var screen = html.get("Races").appendTo(nu.frame.content);

        //tab navigation to subscreens
        screen.tabs.find("li").tclick(function () { window.location = "#/race" + $(this).data("tab"); });

        nu.view.screen = screen;
        
        //remove "unknown"
        var races = new Array();
        var firstset = new Array();
        var secondset = new Array();
        for (var i = 1; i < nudata.races.length; i++) {
            var race = nudata.races[i];

            var fleetadv = 0;
            var basehulls = race.basehulls.split(',');
            for (var j = 0; j < basehulls.length; j++) {
                var hull = nu.getHull(basehulls[j]);
                if (hull != null) {
                    fleetadv += hull.advantage;
                }
            }
            race.fleetadv = fleetadv;

            var raceadv = 0;
            var baseadvantages = race.baseadvantages.split(",");
            for (var j = 0; j < baseadvantages.length; j++) {
                var adv = nu.getAdvantage(baseadvantages[j]);
                if (adv != null)
                    raceadv += adv.value;
            }
            race.raceadv = raceadv;
            race.advantage = fleetadv + raceadv;

            races.push(race);
            if (i <= 6)
                firstset.push(race);
            else
                secondset.push(race);

            race.advantagewidth = race.advantage - 300;
        }

        html.get("RaceList", { races: firstset }).appendTo(screen.tabcontent);
        html.get("RaceList", { races: secondset }).appendTo(screen.tabcontent);
        $("    <div style='clear:both;'></div>").appendTo(screen.tabcontent);

        $(".erendergamerow").tclick(function () { window.location = "#/race/" + $(this).data("id"); });

    }

}

