function ViewContact() { };
ViewContact.prototype = {
    show: function () {
        nu.frame.content.empty();
        nu.frame.find("li").removeClass("esel");
        if (nu.data.account && !nu.data.account.games) {
            nu.api.myGames(nu.data.account, function () { nu.view.show(); });
            return;
        }
        var contact = html.get("ContactScreen", nu.data.account).appendTo(nu.frame.content);
        if (nu.data.account) {
            $("#ContactBoxName").val(nu.data.account.username);
            $("#ContactBoxEmail").val(nu.data.account.email);
            if (nu.data.account.games.length > 0)
                $("#ContactGameSelect").show();
        }

        $("#ContactBoxSubmit").tclick(function () {
            nu.api.contactMessage($("#ContactBoxName").val(), $("#ContactBoxEmail").val(), $("#ContactBoxMessage").val().replace(/\n/g, "<br/>"), $("#ContactGameSelect").val(), function () { $("#ContactBoxSubmit").replaceWith("<span>Message Sent</span>"); });
        });
    }
}

