    postGameMessage: function(body, parentid, to) {

        if (this.sendingMessage)
            return;

        if (this.inHistory || this.isAdminView || this.isMentorView || this.editmode)
            return;

        if (body == "")
            return;

        this.sendingMessage = true;
        this.indicator.text("Sending...");
        this.indicateOn();

        var data = new dataObject();
        data.add("gameid", this.gameId);
        data.add("playerid", this.player.id);
        data.add("apikey", vgap.apikey);
        if (to)
            data.add("to", to);

        if (parentid)
            data.add("parentid", parentid);

        data.add("body", body);

        this.request("/game/sendmessage", data, function (result) {
            if (result) {
                if (result.success) {
                    vgap.activity = result.activity.activity;
                    vgap.processActivity();
                    vgap.dash.summary();
                }
                else {
                    alert(result.error);
                }
                vgap.indicateOff();
            }
            else
                vgap.disconnected();

            vgap.sendingMessage = false;
        });

    },
    sendMessage: function (to, body) {
        if (this.sendingMessage)
            return;

        this.sendingMessage = true;
        this.indicator.text("Sending...");
        this.indicateOn();

        var data = new dataObject();
        data.add("gameid", this.gameId);
        data.add("playerid", this.player.id);
        data.add("apikey", vgap.apikey);
        data.add("to", to);
        data.add("body", body);

        this.request("/game/sendmessage", data, function (result) { vgap.processSendMessage(result); });

    },
    processSendMessage: function (result) {
        if (result) {
            if (result.success) {

                vgap.mymessages = result.mymessages;
                vgap.parseMessages();
                vgap.dash.showPlayerMessages();
                $("#SendMessageResult").html(result.html);

            }
            else {
                alert(result.error);
            }
            this.indicateOff();
        }
        else {
            //We are disconnected from the internet.  Warn the user.
            vgap.disconnected();
        }
        this.sendingMessage = false;
    },
