            //            $.getJSON("http://apitest.planets.nu/game/loadturn?jsoncallback=?&turn=" + this.loadHistoryTurn + "&gameid=" + vgap.gameId + "&apikey=" + vgap.apikey + "&playerid=" + this.player.id, function (result) { vgap.processLoadHistory(result); });


