function addCommas(nStr, negativestoo) {
    if (nStr < 0 && !negativestoo)
        return gsv(nStr);

    nStr += '';
    x = nStr.split('.');
    x1 = x[0];
    x2 = x.length > 1 ? '.' + x[1] : '';
    var rgx = /(\d+)(\d{3})/;
    while (rgx.test(x1)) {
        x1 = x1.replace(rgx, '$1' + ',' + '$2');
    }
    return x1 + x2;
}

jQuery.fn.center = function () {
    this.css("position", "absolute");
    this.css("top", ($(window).height() - this.height()) / 2 + $(window).scrollTop() + "px");
    this.css("left", ($(window).width() - this.width()) / 2 + $(window).scrollLeft() + "px");
    return this;
}
jQuery.fn.upDown = function (onchange, amount, displaymult) {

    var id = this.attr("id");
    var cls = "UpDown";
    if (amount)
        cls += amount;

    this.addClass(cls);
    var ups = $("<div class='ups'/>").appendTo(this);
    $("<div class='udsac' id='1'><div class='uda'/></div>").appendTo(ups);
    if (amount > 1)
        $("<div class='udsac' id='10'><div class='uda'/></div>").appendTo(ups);
    if (amount > 10)
        $("<div class='udsac' id='100'><div class='uda'/></div>").appendTo(ups);
    if (amount > 100)
        $("<div class='udsac' id='1000'><div class='uda' /></div>").appendTo(ups);

    var text = null;
    if (amount)
        text = $("<div class='udtext'></div>").appendTo(this);

    var downs = $("<div class='downs'/>").appendTo(this);
    if (amount > 100)
        $("<div class='udsac' id='-1000'><div class='uda'/></div>").appendTo(downs);
    if (amount > 10)
        $("<div class='udsac' id='-100'><div class='uda'/></div>").appendTo(downs);
    if (amount > 1)
        $("<div class='udsac' id='-10'><div class='uda'/></div>").appendTo(downs);
    $("<div class='udsac' id='-1'><div class='uda'/></div>").appendTo(downs);

    var bindevents = "click touchstart";
    var ua = navigator.userAgent.toLowerCase();
    var isAndroid = ua.indexOf("android") > -1;
    if (isAndroid) 
        bindevents = "touchstart";

    $("#" + id + " .udsac").bind(bindevents, { onchange: onchange }, function (e) { var amount = parseInt(this.id); if (e.ctrlKey || e.shiftKey) amount *= 100000; vgap.playSound("fastbutton"); e.data.onchange(amount); e.preventDefault(); });

    if (amount) {
        $("#" + id + " .udsac").bind('mouseover mousemove', { text: text }, function (e) {
            if (e.ctrlKey || e.shiftKey)
                e.data.text.text("MAX");
            else {
                var val = parseInt(this.id);
                if (displaymult)
                    val *= displaymult;
                var txt = val;
                if (val > 0)
                    txt = "+" + val;
                e.data.text.text(addCommas(txt, true));
            }
        });
        $("#" + id + " .udsac").bind('mouseout', { text: text }, function (e) { e.data.text.text(""); });
    }
    return this;
}
