                //html += "<td>" + hullname + "</td><td>" + (ship.beams > 0 ? vgap.getBeam(ship.beamid).name + " x" + ship.beams : "") + "</td><td>" + (ship.torps > 0 ? vgap.getTorpedo(ship.torpedoid).name + " x" + ship.torps : "") + (ship.bays > 0 ? " Bays x" + ship.bays : "") + (ship.bays > 0 || ship.torps > 0 ? " [" + ship.ammo + "]" : "") + "</td><td>" + ship.clans + "</td><td>" + (ship.readystatus > 0 ? (ship.readystatus == 1 ? "v" : "vv") : "") + "</td>";
                html += "<td>" + hullname + "</td><td>" + (ship.beams > 0 ? vgap.getBeam(ship.beamid).name + " x" + ship.beams : "") + "</td><td>" + (ship.torps > 0 ? vgap.getTorpedo(ship.torpedoid).name + " x" + ship.torps : "") + (ship.bays > 0 ? " Bays x" + ship.bays : "") + (ship.bays > 0 || ship.torps > 0 ? " [" + ship.ammo + "]" : "") + "</td><td>" + ship.clans + "</td><td>" + (ship.readystatus > 0 ? "<div class='readyCheckBox readyCheckBox" + ship.readystatus + "' >" + ship.readystatus + "</div>" : "") + "</td>";

