    getEdgeOpacity: function() {
        if (vgap.map.zoom > 20)
            return 0.05;
        if (vgap.map.zoom > 15)
            return 0.03;
        if (vgap.map.zoom > 10)
            return 0.01;
        return 0;
    },
    drawWormHole: function (x, y, rad, isExit, wormhole, ctx) {
        var opacity = 0.01;
        var edge = vgap.map.getEdgeOpacity();

        var color = "#f69704";
        if (isExit)
            color = "#0497f6";

        var grad = ctx.createRadialGradient(x, y, 0, x, y, rad);
        grad.addColorStop(0, colorToRGBA(color, opacity));
        grad.addColorStop(1, colorToRGBA(color, edge));
        ctx.fillStyle = colorToRGBA(color, opacity);
        ctx.strokeStyle = colorToRGBA(color, opacity);
        ctx.lineWidth = 1;

        /*
        ctx.beginPath();
        ctx.arc(x, y, rad, 0, Math.PI * 2, false);
        ctx.closePath();
        ctx.fill();
        */
        ctx.lineWidth = 1 + rad / 8;
        ctx.lineCap = "round";
        ctx.strokeStyle = colorToRGBA(color, 1);

        var ox = x;
        var oy = y;
        for (i = 0; i <= 1; i += 0.01) {
            ctx.beginPath();
            var angle = i * Math.PI * 4;
            if (isExit)
                angle += Math.PI;
            var sx = x + (rad + i * rad * 1.5) * Math.cos(angle);
            var sy = y + (rad + i * rad * 1.5) * Math.sin(angle);
            ctx.lineWidth = 0.4 + i * rad / 4;
            ctx.strokeStyle = colorToRGBA(color, ((1 - i) * 0.75));
            ctx.moveTo(ox, oy);
            if (ox != x || oy != y)
                ctx.lineTo(sx, sy);
            ctx.stroke();
            ox = sx;
            oy = sy;
        }
    },
    drawStar: function (x, y, star, ctx) {

        var rad = star.radius * vgap.map.zoom;

        var color = "#FF0000";
        if (star.temp > 3000 && star.temp <= 6000)
            color = "#FFA500";
        if (star.temp > 6000 && star.temp <= 10000)
            color = "#A52A2A";
        if (star.temp > 10000 && star.temp <= 20000)
            color = "#FFFFFF";
        if (star.temp > 20000)
            color = "#B0E0E6";

        //radiation
        //var radColor = "#FFA500";
        var opacity = Math.max(0.4 * star.temp / 65000, 0.2);
        var edge = vgap.map.getEdgeOpacity();

        var effectRad = Math.sqrt(star.mass) * vgap.map.zoom;
        var grad = ctx.createRadialGradient(x, y, 0, x, y, effectRad);
        grad.addColorStop(0, colorToRGBA(color, opacity));
        grad.addColorStop(1, colorToRGBA(color, edge));
        ctx.fillStyle = grad;

        ctx.beginPath();
        ctx.arc(x, y, effectRad, 0, Math.PI * 2, false);
        ctx.closePath();
        ctx.fill();

        //if (this.zoom > 40) {
        //    ctx.strokeStyle = colorToRGBA(color, 0.25);
        //    ctx.stroke();
        //}


        //circle
        var grad = ctx.createRadialGradient(x, y, 0, x, y, rad);
        grad.addColorStop(0, colorToRGBA(color, 0.25));
        grad.addColorStop(1, colorToRGBA(color, 0.05));
        ctx.fillStyle = grad;

        ctx.beginPath();
        ctx.arc(x, y, rad, 0, Math.PI * 2, false);
        ctx.closePath();
        ctx.fill();

        //diamond
        var halfRad = rad / 4;
        var grad = ctx.createRadialGradient(x, y, 0, x, y, halfRad);
        grad.addColorStop(0, colorToRGBA(color, 1));
        grad.addColorStop(1, colorToRGBA(color, 0));
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.moveTo(x - halfRad, y);
        ctx.lineTo(x, y - halfRad);
        ctx.lineTo(x + halfRad, y);
        ctx.lineTo(x, y + halfRad);
        ctx.closePath();
        ctx.fill();
    },
