    drawIon: function (x, y, voltage, rad, ctx, storm) {

        var opacity = voltage / 400;
        if (opacity > 1)
            opacity = 1;
        if (opacity < 0.1)
            opacity = 0.1;
        var color = vgap.accountsettings.ionstorms;

        var grad = ctx.createRadialGradient(x, y, 0, x, y, rad);
        grad.addColorStop(0, colorToRGBA(color, opacity));
        if (vgap.settings.nuionstorms)
            grad.addColorStop(1, colorToRGBA(color, vgap.map.getEdgeOpacity()));
        else
            grad.addColorStop(1, colorToRGBA(color, 0.05));
        ctx.fillStyle = grad;

        ctx.strokeStyle = colorToRGBA(color, 0.05);
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(x, y, rad, 0, Math.PI * 2, false);
        ctx.closePath();
        ctx.fill();

        if (!vgap.settings.nuionstorms)
            ctx.stroke();

        //center dot
        if (storm.parentid == 0) {

            if (storm.centroid) {
                x = this.screenX(storm.centroid.x);
                y = this.screenY(storm.centroid.y);
            }

            ctx.fillStyle = colorToRGBA(vgap.accountsettings.ionstorms, 0.5);
            ctx.beginPath();
            ctx.arc(x, y, 1, 0, Math.PI * 2, false);
            ctx.closePath();
            ctx.fill();
        }

    },
    shipRad: function (ship) {


        var rad = 3;
        if (ship.mass < 800)
            rad = 2;

        if (this.zoom < 1)
            rad = Math.round(rad * this.zoom);
        else
            rad = Math.round(rad * Math.pow(this.zoom, 0.3));

        if (this.zoom > 40 && vgap.animations)
            rad += this.zoom / 8;

        if (vgap.replay.running)
            rad *= 2;


        return rad;
    },
