    drawShip: function(ship, ctx) {

        var x = this.screenX(ship.x);
        var y = this.screenY(ship.y);
        var rad = this.shipRad(ship);

        var grad = ctx.createLinearGradient(x-rad, y-rad, x+rad, y+rad);
        grad.addColorStop(0, ship.colorfrom);
        grad.addColorStop(1, ship.colorto);
        ctx.fillStyle = grad;
        
        if (this.zoom > 40 && vgap.animations && vgap.map.fastrendering) {

            if (!ship.rndX) {
                ship.rndX = Math.random();
                ship.rndY = Math.random();
            }

            var rnd = this.zoom / 2;
            x += (ship.rndX * rnd) - (rnd / 2);
            y += (ship.rndY * rnd) - (rnd / 2);

            //draw the image of the planet
            if (!ship.imgObj) {
                ship.imgObj = new Image();
                ship.imgObj.onload = function () { vgap.map.draw(); };
                ship.imgObj.src = ship.img;
            }
            else {
                if (ship.iscloaked)
                    ctx.globalAlpha = 0.75;

                ctx.drawImage(ship.imgObj, x - rad, y - rad, rad * 2, rad * 2);
                ctx.globalAlpha = 1;

                //tint image code (but should be drawn to another canvas first 
                //var data = ctx.getImageData(x - rad, y - rad, rad * 2, rad * 2);
                //for (var i = 0, length = data.data.length; i < length; i += 4) {
                //    data.data[i] = Math.max(255, data.data[i]);
                //}
                //ctx.putImageData(data, x - rad, y - rad);                
            }
        }
        else {

            ctx.beginPath();
            ctx.arc(x, y, rad, 0, Math.PI * 2, false);
            ctx.closePath();
            ctx.fill();
        }
    },
    planetRad: function (planet) {
        if (!planet)
            planet = {};

        var rad = 6;
        if (planet.debrisdisk || vgap.settings.isacademy)
            rad = 1;

        if (vgap.map.zoom < 1)
            return Math.round(rad * vgap.map.zoom);

        rad = Math.round(rad * Math.pow(vgap.map.zoom, 0.4));

        if (this.zoom > 20 && vgap.animations) {
            if (planet.debrisdisk)
                rad += this.zoom / 5;
            else if (vgap.settings.isacademy)
                rad += this.zoom / 3;
            else
                rad += this.zoom / 2; //normal planets are bigger
        }
        
        return rad;
    },
