//http://www.allegro.cc/forums/thread/589720
function closestDistance(x, y, x1, y1, x2, y2) {

    var A = x - x1;
    var B = y - y1;
    var C = x2 - x1;
    var D = y2 - y1;

    var dot = A * C + B * D;
    var len_sq = C * C + D * D;
    var param = dot / len_sq;

    var xx, yy;

    if (param < 0 || (x1 == x2 && y1 == y2)) {
        xx = x1;
        yy = y1;
    }
    else if (param > 1) {
        xx = x2;
        yy = y2;
    }
    else {
        xx = x1 + param * C;
        yy = y1 + param * D;
    }

    var dx = x - xx;
    var dy = y - yy;
    return Math.sqrt(dx * dx + dy * dy);
}

var indexedDB = window.indexedDB || window.webkitIndexedDB || window.mozIndexedDB;

if ('webkitIndexedDB' in window) {
    window.IDBTransaction = window.webkitIDBTransaction;
    window.IDBKeyRange = window.webkitIDBKeyRange;
}

var idb = {};
idb.open = function (name) {
    return;
    if (!indexedDB)
        return;

    try {
        var request = indexedDB.open(name);
        request.onsuccess = function (e) { log("opened: " + name); idb.db = e.target.result; idb.create("keypairs"); };
        request.onfailure = function (e) { log(e); };
    }
    catch (e) {
        log(e);
        return;
    }
};
idb.create = function (storename) {
    // We can only create Object stores in a setVersion transaction;
    var ver = "1.01";
    if (ver != idb.db.version) {
        var request = idb.db.setVersion(ver);

        // onsuccess is the only place we can create Object Stores
        request.onfailure = function (e) {  };
        request.onsuccess = function (e) {
            if (idb.db.objectStoreNames.contains(storename))
                idb.db.deleteObjectStore(storename);
            var store = idb.db.createObjectStore(storename);
            log("Created: ", store);
        };
    }
};
idb.setObject = function (key, obj) {
    if (!indexedDB)
        return;

    try {
        var trans = idb.db.transaction(["keypairs"], IDBTransaction.READ_WRITE, 0);
        var store = trans.objectStore("keypairs");
        var request = store.put(obj, key);
        request.onerror = function (e) { log("Error Adding: ", e); };
        request.onsuccess = function (e) { log("Added: ", e); };
    } catch (err) {
        log("Cache error: ", err);
    }
};
idb.getObject = function (key, callback) {

    //idb temporarily disabled 12-17-2011

    //if (!indexedDB) { 
    callback(null);
    return;
    //}

    try {
        var trans = idb.db.transaction(["keypairs"], IDBTransaction.READ_WRITE, 0);
        var store = trans.objectStore("keypairs");
        log("Getting item: " + key);
        var request = store.get(key);
        request.onsuccess = function (e) { log("found: " + key); callback(e.target.result); };
        request.onerror = function (e) { log("not found: " + key); callback(null); };
    }
    catch (err) {
        log(err);
        callback(null);
    }
};

window.log = function () { log.history = log.history || []; log.history.push(arguments); if (this.console) { console.log(Array.prototype.slice.call(arguments)) } };


