            html += "<tr><td><img src='http://play.planets.nu/img/icons/factory.png'/></td><td><table><tr><td>" + nu.t.factories + ":</td><td>" + planet.factories + "</td><td class='valsup'>(+" + planet.builtfactories + ")</span></td></tr><tr><td>" + nu.t.max + ":</td><td>" + this.maxBuilding(100) + "</td></tr><tr><td>" + nu.t.target + ":</td><td><input id='TargetFactories' type='text' maxlength='3' value='" + planet.targetfactories + "'/></td></tr></table></td><td><div id='BuildFactories'/></td><td><span class='valsup'>" + nu.t.factoriescost + ":<br/>4 Megacredits</span></td></tr>";
            html += "<tr><td><img src='http://play.planets.nu/img/icons/defense.png'/></td><td><table><tr><td>" + nu.t.defense + ":</td><td>" + planet.defense + "</td><td class='valsup'>(+" + planet.builtdefense + ")</span></td></tr><tr><td>" + nu.t.max + ":</td><td>" + this.maxBuilding(50) + "</td></tr><tr><td>" + nu.t.target + ":</td><td><input id='TargetDefense' type='text' maxlength='3' value='" + planet.targetdefense + "'/></td></tr></table></td><td><div id='BuildDefense'/></td><td><span class='valsup'>" + nu.t.defensecost + ":<br/>11 Megacredits</td></tr></table>";
            html += "<p>" + vgap.planetDefenseAbility(planet) + "</p>";
