            $("#BuildFactories").upDown(function (change) { vgap.planetScreen.changeFactories(change); }, 10);
            $("#BuildDefense").upDown(function (change) { vgap.planetScreen.changeDefense(change); }, 10);
            $("#SellSupplies").leftRight(function (change) { vgap.planetScreen.sellSupplies(change); }, 1000);
