        html += "<p><label>R Bonus Mass:</label><select id='RBonusMass' class='SimExtraShort'><option value='random'>Random</option><option value='on'>Always On</option><option value='off'>Always Off</option></select></p>";
        html += "</div></td>";

        html += "<td><div style='padding: 0px 50px;'>"
        html += "<p>Fast Compute</p>"
        html += "<p><a id='FastComputeButton' class='elinkbutton' style='float: none; margin: 0px;'>Start</a></p>";
        html += "</div></td>";

        html += "<td><div style='padding: 0px 50px;'>";
