    oneTransferTarget: function () {
        for (var i = 0; i < this.ships.length; i++) {
            if (this.ships[i].ownerid == this.planet.ownerid)
                vgap.transferScreen.planetToShip(this.planet.id, this.ships[i].id);
        }
    },
    transfer: function () {

        vgap.more.empty();
        var count = 0;
        $("<div id='SelectLocation'><h1>" + nu.t.selecttransfertarget + "</h1></div>").appendTo(vgap.more);
        vgap.transferScreen.onchange = function () { vgap.starbaseScreen.updateTransfer(); };
        for (var i = 0; i < this.ships.length; i++) {
            if (this.ships[i].ownerid == this.planet.ownerid) {
                count++;
                var select = function(planetid, id) { return function() { vgap.transferScreen.planetToShip(planetid, id); }; }; //closure
                $(shtml.shipTransferView(this.ships[i])).tclick(select(this.planet.id, this.ships[i].id)).appendTo("#SelectLocation");
            }
        }
        shtml.moreBack();

        if (count == 1) {
            this.oneTransferTarget();
            return;
        }
              
        vgap.showMore(330);
        if ($("#SelectLocation").height() > ($(window).height() - 100))
            $("#SelectLocation").height($(window).height() - 100);
        $("#SelectLocation").jScrollPane();
    },
    updateTransfer: function () {
        this.screen.refresh();
    },
