    buildToggle: function (section) {
        $("#BuildShipScreen .BuildContainer").height(0);
        hght = $(window).height() - 178 + "px";
        $("#" + section).height(hght);
        if (section == 'ShipAssembly')
            this.showAssembly();
        if (section == "ShipHulls")
            this.showBuyHull(vgap.racehulls[0]);
        if (section == "ShipEngines")
            this.showBuyEngine(1);
        if (section == "ShipBeams")
            this.showBuyBeam(1);
        if (section == "ShipLaunchers")
            this.showBuyLauncher(1);

    },
    getStockText: function (stockType, stockId) {
        var item = vgap.getStock(this.starbase.id, stockType, stockId);
        var txt = item.amount;
        if (item.builtamount > 0)
            txt += " <span class='valsup'>(+" + item.builtamount + ")</span>";
        return txt;
    },
