    techCost: function (lvl) {
        if (lvl == 10)
            return "Max";

        if (lvl >= 7 && !vgap.player.isregistered && this.planet.flag != 1)
            return "Max";

        var next = lvl + 1;
        return "Tech " + lvl + " to tech " + next + "<br/>" + lvl + "00 Megacredits";
    },
    changeHullTech: function (change, refresh) {
        var planet = this.planet;
        var starbase = this.starbase;
        var cost = starbase.hulltechlevel * 100;
        var max = 7;
        if (vgap.player.isregistered || planet.flag == 1) 
            max = 10;

        //kind of a hack
        if (vgap.settings.isacademy)
            planet = vgap.player;

        if (change > 0) {
            if (planet.megacredits < cost || starbase.hulltechlevel >= max)
                return false;

            planet.megacredits -= cost;
            starbase.hulltechlevel++;
            starbase.hulltechup++;
        }
        else {
            if (starbase.hulltechup < 1)
                return false;

            if (this.stockBuilt(1, starbase.hulltechlevel)) {
                $("#StockBuiltWarning").text("Hulls have been bought at this tech level. Remove hulls to lower.");
                return false;
            }

            planet.megacredits += (cost - 100);
            starbase.hulltechlevel--;
            starbase.hulltechup--;
        }
        if (refresh) {
            this.screen.refresh();
            this.raiseTech();
        }

        vgap.map.updateAcademyResources();

        vgap.action();
        return true;
    },
