        $("#BuildDefense").upDown(function (change) { vgap.starbaseScreen.changeDefense(change); }, 10);
        $("#SellSupplies").leftRight(function (change) { vgap.starbaseScreen.sellSupplies(change, 'defense'); }, 1000);
