var RANDOM_SIZE = 119;
var MAX_BEAMS = 10;
var MAX_TORPS = 10;
var MAX_FIGHTERS = 19;
var SHIP_TO_SHIP = 0;
var SHIP_TO_PLANET = 1;

function combatObject() { };

combatObject.prototype = {
    init: function () {
        this.BeamCount = 0;
        this.LauncherCount = 0;
        this.BayCount = 0;
        this.Shield = 100;
        this.Damage = 0;
        this.Crew = 0;
        this.CrewMax = 0;
        this.RaceId = 0;
        this.Mass = 0;
        this.Torpedos = 0;
        this.Fighters = 0;
        this.BeamKillBonus = 1;
        this.BeamChargeRate = 1;
        this.TorpChargeRate = 1;
        this.TorpMissPercent = 35;
        this.TorpRange = 300;
        this.CrewDefensePercent = 0;

        this.BeamsCharge = new Array(MAX_BEAMS);
        this.TorpedoCharge = new Array(MAX_TORPS);
        this.FighterActive = new Array(MAX_FIGHTERS);
        this.FighterX = new Array(MAX_FIGHTERS);
        this.CurrentX = 0;
        this.DamageLimit = 100;
    },
    setObject: function (obj) {

        this.init();

        this.BayCount = obj.baycount;
        this.BeamCount = obj.beamcount;
        this.LauncherCount = obj.launchercount;
        this.TorpedoId = obj.torpedoid;
        if (obj.torpedoid == 11)
            this.TorpRange = 340;

        this.BeamId = obj.beamid;
        this.Crew = obj.crew;
        this.Mass = obj.mass;
        this.Fighters = obj.fighters;
        this.Torpedos = obj.torpedos;
        this.Damage = obj.damage;
        this.Shield = obj.shield;
        this.RaceId = obj.raceid;
        if (obj.beamkillbonus)
            this.BeamKillBonus = obj.beamkillbonus;
        else if (obj.raceid == 5)
            this.BeamKillBonus = 3;
        if (obj.beamchargerate)
            this.BeamChargeRate = obj.beamchargerate;
        if (obj.torpchargerate)
            this.TorpChargeRate = obj.torpchargerate;
        if (obj.torpmisspercent)
            this.TorpMissPercent = obj.torpmisspercent;
        if (obj.crewdefensepercent)
            this.CrewDefensePercent = obj.crewdefensepercent;

        if (obj.torpedoid) {
            var torp = vgap.getTorpedo(obj.torpedoid);
            this.TorpRange = vgap.getTorpRange(torp);
        }

        if (obj.hullid) {
            var hull = vgap.getHull(obj.hullid);
            this.CrewMax = hull.crew;
        }

    },
    setShip: function (ship) {

        init();

        this.BayCount = ship.bays;
        this.BeamCount = ship.beams;
        this.LauncherCount = ship.torps;
        this.TorpedoId = ship.torpedoid;
        this.BeamId = ship.beamid;
        this.Crew = ship.crew;
        this.Mass = ship.mass;
        if (this.BayCount > 0)
            this.Fighters = ship.ammo;
        if (this.LauncherCount > 0)
            this.Torpedos = ship.ammo;

    }
}


